import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Read integers n and mod
        int n = sc.nextInt();
        int mod = sc.nextInt();

        // Initialize mem array and su variable
        long[] mem = new long[n + 1];
        mem[0] = 0;
        mem[1] = 1;
        long su = 1;

        // Helper functions
        java.util.function.BiFunction<Long, Long, Long> add = (a, b) -> (a + b) % mod;
        java.util.function.BiFunction<Long, Long, Long> mult = (a, b) -> (a * b) % mod;

        for (int i = 2; i <= n; i++) {
            int sq = (int)(Math.sqrt(i)) + 1;
            long cur = su;

            // For loop for range 2 to sq
            for (int f = 2; f < sq; f++) {
                long index = i / f;
                // Ensure index within bounds
                if (index < mem.length) {
                    cur = add.apply(cur, mem[(int)index]);
                }
            }

            long be = i;
            // Loop for j in 1 to i / sq
            for (int j = 1; j <= i / sq; j++) {
                long nxt = i / (j + 1);
                long addend = (be - nxt);
                if (addend < 0) addend += mod; // ensure non-negative before multiplication
                long temp = mult.apply(addend, mem[(int)j]);
                cur = add.apply(cur, temp);
                be = nxt;
            }

            su = add.apply(su, cur);
            mem[i] = cur;
        }

        System.out.println(mem[n]);
        sc.close();
    }
}
